//! Faber's attention chime for the sidecar, which has no window to play it in: the same sound the Tauri shell embeds.
//! On Windows it plays from memory; elsewhere the system's own player plays a copy kept in the data folder.

// The chime is generated by one function the Tauri shell's build script also runs; it moves here with phase 7 (R459).
#[path = "../../../src-tauri/chime.rs"]
mod source;

use std::sync::OnceLock;

/// The chime as a WAVE file, made once.
fn wav() -> &'static [u8] {
    static WAV: OnceLock<Vec<u8>> = OnceLock::new();
    WAV.get_or_init(source::wav)
}

/// Plays the chime without waiting for it. A sound that cannot play is not worth more than a line in the log.
pub fn play(data_dir: &std::path::Path) {
    if let Err(error) = start(data_dir) {
        eprintln!("faber: the attention chime did not play: {error}");
    }
}

#[cfg(windows)]
fn start(_data_dir: &std::path::Path) -> std::io::Result<()> {
    faber_winproc::sound::play_wave(wav())
}

#[cfg(not(windows))]
fn start(data_dir: &std::path::Path) -> std::io::Result<()> {
    use std::process::{Command, Stdio};
    let path = data_dir.join("attention.wav");
    if std::fs::read(&path).ok().as_deref() != Some(wav()) {
        std::fs::write(&path, wav())?;
    }
    #[cfg(target_os = "macos")]
    let players = ["/usr/bin/afplay"];
    #[cfg(not(target_os = "macos"))]
    let players = ["paplay", "aplay"];
    // The player runs on its own thread, so a slow one never holds the order that asked for it.
    std::thread::spawn(move || {
        for player in players {
            let ran = Command::new(player).arg(&path).stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null()).status();
            if ran.is_ok_and(|status| status.success()) {
                return;
            }
        }
    });
    Ok(())
}

#[cfg(test)]
mod tests {
    #[test]
    fn the_sidecar_plays_the_same_chime_as_the_shell() {
        let wav = super::wav();
        assert!(faber_winproc::sound::whole_wave(wav), "a whole WAVE, which Windows plays from memory");
        assert_eq!(wav, super::source::wav().as_slice());
        assert!(std::ptr::eq(wav, super::wav()), "made once");
    }
}
